95	// The CSP header is the machine-checkable no-egress proof; it must be present on
96	// every response.
97	func TestVizSecurityHeaders(t *testing.T) {
98		t.Parallel()
99		h := vizSecurityHeaders(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) }))
100		rec := httptest.NewRecorder()
101		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
102		csp := rec.Header().Get("Content-Security-Policy")
103		if csp == "" {
104			t.Fatal("missing Content-Security-Policy header")
105		}
106		for _, want := range []string{"default-src 'self'", "connect-src 'self'", "script-src 'self'", "form-action 'none'", "object-src 'none'"} {
