134	// The graph's relations query binds every symbol id TWICE (from_id + to_id). A
135	// large view must NOT exceed SQLITE_MAX_VARIABLE_NUMBER (~32766) — the query is
136	// chunked. With 20k symbols the old single query bound 40001 params and errored,
137	// which silently produced a zero-edge graph that collapses to a dot.
138	func TestFindSemanticRelationsForSymbols_ChunksLargeInClause(t *testing.T) {
139		t.Parallel()
140		dbPath := filepath.Join(t.TempDir(), "semantic.sqlite")
141		db, err := sql.Open(sqlitedriver.Name, dbPath)
142		if err != nil {
143			t.Fatalf("open: %v", err)
144		}
145		if _, err := db.Exec(`CREATE TABLE relations (id INTEGER PRIMARY KEY, from_id TEXT, to_id TEXT, type TEXT, confidence REAL, reason TEXT)`); err != nil {
146			t.Fatalf("create: %v", err)
147		}
148		// rowid 1: sym-1 -> sym-2 ; rowid 2: sym-3 -> sym-1 (both incident to the set)
149		if _, err := db.Exec(`INSERT INTO relations (from_id,to_id,type,confidence,reason) VALUES ('sym-1','sym-2','CALLS',1,''),('sym-3','sym-1','IMPORTS',1,'')`); err != nil {
150			t.Fatalf("insert: %v", err)
151		}
152		db.Close()
153	
154		syms := make([]semanticRecord, 20000) // 40001 bound params unchunked -> would error
155		for i := range syms {
156			syms[i] = semanticRecord{ID: fmt.Sprintf("sym-%d", i+1)}
157		}
158		rels, err := findSemanticRelationsForSymbolsInSQLite(dbPath, syms, 1000)
159		if err != nil {
160			t.Fatalf("large symbol set errored (chunking regression): %v", err)
161		}
162		if len(rels) != 2 {
163			t.Fatalf("got %d relations, want 2", len(rels))
164		}
165		if rels[0].FromID != "sym-1" || rels[1].FromID != "sym-3" {
166			t.Fatalf("relations not merged in rowid order across chunks: %+v", rels)
167		}
168	}
