172	// ceiling — no query parameter can request an unbounded graph.
173	func TestVizQueryLimit_ClampsToSafetyCeiling(t *testing.T) {
174		t.Parallel()
175		cases := []struct {
176			query string
177			def   int
178			want  int
179		}{
180			{"", 3000, 3000},
181			{"limit=25", 3000, 25},
182			{"limit=0", 3000, vizGraphMaxView},
183			{"limit=99999999", 3000, vizGraphMaxView},
184			{"limit=-5", 3000, 3000},
185			{"limit=abc", 3000, 3000},
186		}
187		for _, tc := range cases {
