429			if !strings.Contains(got, want) {
430				t.Fatalf("files: %q missing %q", got, want)
431			}
432		}
433		if strings.Contains(got, "more)") {
434			t.Fatalf("files: unexpected overflow note in %q", got)
435		}
436		many := make([]string, 0, 11)
437		for i := 0; i < 11; i++ {
438			many = append(many, fmt.Sprintf("dir/f%d.go", i))
439		}
440		over := vizSessionFallbackText(exportSession{FilesTouched: many})
441		if !strings.Contains(over, "_(+3 more)_") { // 11 touched, 8 shown -> 3 more
442			t.Fatalf("overflow: %q missing the +3 more note", over)
443		}
444		if n := strings.Count(over, "- f"); n != 8 { // exactly 8 file bullets are shown
445			t.Fatalf("overflow: got %d file bullets, want 8 in %q", n, over)
446		}
