20	// writeVizOptimizationStore builds a Graph-owned store fixture (sqlite with the
21	// brain_*_v1 views and entry digest) and returns its live source descriptor,
22	// the only shape the viz read path accepts since the snapshot reader retired.
23	func writeVizOptimizationStore(t *testing.T, brainDir string, records []semanticRecord) *semanticSourceManifest {
24		t.Helper()
25		var body strings.Builder
26		body.WriteString(`{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"c1","tree":"t1","capabilities":["go"],"warnings":[],"partial_failures":[]}` + "\n")
27		for _, record := range records {
28			line, err := json.Marshal(record)
29			if err != nil {
30				t.Fatal(err)
31			}
32			body.Write(line)
33			body.WriteByte('\n')
34		}
35		repoDir := t.TempDir()
36		ignore, err := loadBrainIgnore(repoDir)
37		if err != nil {
38			t.Fatal(err)
39		}
40		header, counts, filtered, err := filterSemanticSnapshot([]byte(body.String()), ignore, repoDir)
41		if err != nil {
42			t.Fatal(err)
43		}
44		providerDir := t.TempDir()
45		generation, _, err := buildSemanticGeneration(context.Background(), providerDir, repoDir, "viz", bytes.NewReader(filtered), "viz", header, counts, time.Now())
46		if err != nil {
47			t.Fatal(err)
48		}
49		path := filepath.Join(providerDir, generation, semanticSQLiteName)
50		db, err := sql.Open(sqlitedriver.Name, path)
51		if err != nil {
52			t.Fatal(err)
53		}
54		for _, table := range []string{"symbols", "relations", "files", "reverse_relations", "symbol_fts"} {
55			if _, err = db.Exec("CREATE VIEW brain_" + table + "_v1 AS SELECT * FROM " + table); err != nil {
56				db.Close()
57				t.Fatal(err)
58			}
59		}
60		raw, _ := json.Marshal("viz-fixture")
61		_, err = db.Exec("INSERT INTO meta(key,value) VALUES('entry_digest',?)", string(raw))
62		db.Close()
63		if err != nil {
64			t.Fatal(err)
65		}
66		d := graphStoreDescriptor{ContractVersion: 1, Path: path, EntryDigest: "viz-fixture", Commit: header.Commit, Tree: header.Tree, Header: header, Files: counts.Files, Symbols: counts.Symbols, Relations: counts.Relations}
67		return graphStoreSource(d, brainDir)
68	}
